<?php
require_once __DIR__.'/config/config.php';require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';$sayfa_baslik='Ligler';$aktif='ligler';require_once __DIR__.'/includes/header.php';
$ligler=$pdo->query("SELECT l.*,COUNT(g.id) grup_sayisi FROM ligler l JOIN sezonlar s ON s.id=l.sezon_id LEFT JOIN gruplar g ON g.lig_id=l.id WHERE l.aktif=1 AND s.durum='aktif' GROUP BY l.id ORDER BY l.created_at")->fetchAll();?>
<main class="main-content"><section class="page-heading"><span>Lig merkezi</span><h1>Ligler</h1><p>Takım ve bireysel okçuluk liglerini, grup ve puan durumlarıyla takip edin.</p></section><div class="lig-kartlari"><?php foreach($ligler as $l):?><a class="lig-karti" href="<?= BASE_URL ?>/lig.php?id=<?= (int)$l['id'] ?>"><span class="eyebrow"><?= $l['tur']==='bireysel'?'Bireysel Okçuluk':'Takım Karşılaşmaları' ?></span><h2><?= e($l['lig_adi']) ?></h2><p><?= e($l['aciklama']?:'Lig gruplarını ve puan durumunu inceleyin.') ?></p><small><?= e($l['sezon']) ?> · <?= (int)$l['grup_sayisi'] ?> grup</small></a><?php endforeach;?></div></main>
